/* ---------- musica di sottofondo (due brani uniti in un unico loop, in mi) ---------- */
const MUS={url:'/audio/theme.mp3?v=8bf8ec5259e5',buf:null,src:null,gain:null,loading:false,vol:.3};
const musOn=()=>!G||G.music!==false;
window.MUSDBG=()=>({buf:!!MUS.buf,dur:MUS.buf?+MUS.buf.duration.toFixed(1):0,playing:!!MUS.src,ac:AC?AC.state:'-'});
async function musStart(){ if(!musOn()||MUS.src||MUS.loading) return; try{ AC=AC||new (window.AudioContext||window.webkitAudioContext)(); if(AC.state==='suspended') await AC.resume();
  if(!MUS.buf){ MUS.loading=true; const res=await fetch(MUS.url,{cache:'force-cache'}); if(!res.ok) throw new Error('Music HTTP '+res.status); const ab=await res.arrayBuffer(); MUS.buf=await new Promise((ok,ko)=>AC.decodeAudioData(ab,ok,ko)); MUS.loading=false; }
  if(!musOn()||MUS.src) return; const g=AC.createGain(), n=AC.currentTime; g.gain.setValueAtTime(0,n); g.gain.linearRampToValueAtTime(MUS.vol,n+2.5); const s=AC.createBufferSource(); s.buffer=MUS.buf; s.loop=true; s.connect(g); g.connect(AC.destination); s.start(); MUS.src=s; MUS.gain=g; }catch(e){ MUS.loading=false; } }
function musStop(){ if(!MUS.src||!AC) return; const s=MUS.src, g=MUS.gain, n=AC.currentTime; g.gain.cancelScheduledValues(n); g.gain.setValueAtTime(g.gain.value,n); g.gain.linearRampToValueAtTime(0,n+.6); setTimeout(()=>{ try{ s.stop(); }catch(e){} },700); MUS.src=null; }
['pointerdown','keydown','touchstart'].forEach(ev=>window.addEventListener(ev,e=>{ if(e.target&&e.target.closest&&e.target.closest('[data-act="music"]')) return; musStart(); },true));
document.addEventListener('visibilitychange',()=>{ if(!AC) return; if(document.hidden) AC.suspend(); else AC.resume(); });
const TOAST_NO=/installat|costruit|rimoss|spostat|Musica (accesa|spenta)|nel tuo roster|creata\.|Modalità libera|Sandbox|prima missione|first mission|Tutorial saltato|Tutorial skipped|Partita cancellata|Saved game deleted|Tutorial finito|Tutorial done|Pianta (aggiunta|rimossa)|Pubblicata in bacheca|rimossa dalla bacheca|Sei tornato alla fase|Stipendi della|Pezzi comprati|accetta la controproposta|è sulla postazione|è sulla rampa|Rata PDR|Nessuna nuova rata|Prima rata|Fase A: rientra|finanzia la missione|assemblaggio completato|Fase B: (esci|vai al)|è assemblato: esci|comincia la fase E|è in orbita: esci|in volo: segui la telemetria|Fase C: costruisci/;
// schermi della sala controllo: tocchi uno schermo e si apre in grande (come il taccuino); quello di stato porta con sé le risorse di bordo
const MZOOM=(()=>{ let el=null, home=null, dash=null, dashHome=null;
  function close(){ if(!el) return; if(home&&home.parent&&home.parent.isConnected) home.parent.insertBefore(el,home.next&&home.next.parentNode===home.parent?home.next:null); if(dash&&dashHome&&dashHome.isConnected) dashHome.appendChild(dash); ['#mzoomBg','#mzoomBox'].forEach(q=>{ const x=$(q); if(x) x.remove(); }); el=null; home=null; dash=null; dashHome=null; }
  function open(t){ close(); el=t; home={parent:t.parentNode,next:t.nextSibling}; document.body.insertAdjacentHTML('beforeend','<div id="mzoomBg"></div><div id="mzoomBox" role="dialog" aria-modal="true"><button class="mzx" type="button" aria-label="'+TX('Chiudi','Close')+'">✕</button><div class="mzin"></div></div>'); const inn=$('#mzoomBox .mzin'); inn.appendChild(t);
    if(t.querySelector('#vit')){ const d=$('#dashw'); if(d){ dash=d; dashHome=d.parentNode; inn.appendChild(d); } } sfx.tap(); try{ mccRefresh(true); }catch(e){} }
  document.addEventListener('click',e=>{ const x=e.target; if(!x||!x.closest) return; if(x.id==='mzoomBg'||x.closest('#mzoomBox .mzx')){ e.stopPropagation(); close(); return; } if(x.closest('#mzoomBox')||view!=='mcc') return;
    const t=x.closest('.mccw.fsc .scr, .mccw.fsc .fmon'); if(!t||x.closest('button,a,input,select,[data-act]')) return; e.stopPropagation(); open(t); },true);
  addEventListener('keydown',e=>{ if(e.key==='Escape') close(); });
  return {open,close}; })();
// telefono: al primo tocco schermo intero e orizzontale, dove il browser lo permette (Android; su iPhone serve «Aggiungi alla schermata Home»)
(()=>{ if(!matchMedia('(pointer:coarse)').matches) return; let done=false; const go=()=>{ if(done) return; done=true; const d=document.documentElement; try{ if(!document.fullscreenElement&&d.requestFullscreen) d.requestFullscreen({navigationUI:'hide'}).then(()=>{ try{ screen.orientation&&screen.orientation.lock&&screen.orientation.lock('landscape').catch(()=>{}); }catch(e){} }).catch(()=>{}); }catch(e){} }; addEventListener('pointerup',go,{once:true,capture:true}); })();
const TOAST_NAV=/(head to the|now head|ora vai|esci e (vai|portalo)|portalo al|porta il satellite su|go to the administration building|vai all[’'`]edificio|: integra(zione|tion) \d+%|in integration \d+%)/i;
function toast(t){ try{ ZORTY.note(t); }catch(e){} if(G&&G.tut) return; const s=String(t); if(TOAST_NO.test(s)||TOAST_NAV.test(s)) return; if(document.body.classList.contains('decon')) return; const el=$('#toast'); el.textContent=s; el.hidden=false; if(!el.dataset.tap){ el.dataset.tap=1; el.addEventListener('click',()=>{ el.hidden=true; clearTimeout(toast.t); }); } clearTimeout(toast.t); toast.t=setTimeout(()=>{el.hidden=true;},Math.min(3200,1600+s.length*22)); }

