    nasa:()=>{ let s=''; for(let i=0;i<7;i++) s+=R(0,i*54/7,54,54/14,'#B22234'); s+=R(0,54/7*0+0,54,0,'#fff'); let r=R(0,0,54,54,'#fff')+s+R(0,0,26,29,'#3C3B6E'); for(let y=0;y<4;y++) for(let x=0;x<4;x++) r+='<circle cx="'+(4+x*6+(y%2)*3)+'" cy="'+(4+y*6.5)+'" r="1.1" fill="#fff"/>'; return r; },
    asi:()=>V3('#009246','#fff','#CE2B37'),
    esa:()=>{ let r=R(0,0,54,54,'#003399'); for(let i=0;i<12;i++){ const a=i*Math.PI/6; r+=star(27+Math.cos(a)*15,27+Math.sin(a)*15,2.6,'#FFCC00'); } return r; },
    csa:()=>R(0,0,54,54,'#fff')+R(0,0,13,54,'#D52B1E')+R(41,0,13,54,'#D52B1E')+'<path d="M27 13l2.5 5 3-1.5-1 7 4-4 1 2.5 4-.8-1.5 4.5 2 1-7 6 .8 2.5-6.8-1.2.3 7h-2.6l.3-7-6.8 1.2.8-2.5-7-6 2-1-1.5-4.5 4 .8 1-2.5 4 4-1-7 3 1.5z" fill="#D52B1E"/>',
    jaxa:()=>R(0,0,54,54,'#fff')+'<circle cx="27" cy="27" r="12" fill="#BC002D"/>',
    isro:()=>H3('#FF9933','#fff','#138808')+'<circle cx="27" cy="27" r="6.5" fill="none" stroke="#000080" stroke-width="1.4"/><circle cx="27" cy="27" r="1.4" fill="#000080"/>',
    kasa:()=>R(0,0,54,54,'#fff')+'<path d="M17 27a10 10 0 0 1 20 0a5 5 0 0 1-10 0a5 5 0 0 0-10 0z" fill="#CD2E3A"/><path d="M17 27a10 10 0 0 0 20 0a5 5 0 0 0-10 0a5 5 0 0 1-10 0z" fill="#0047A0"/>'+[[9,11,-1],[45,11,1],[9,43,1],[45,43,-1]].map(p=>'<g transform="translate('+p[0]+' '+p[1]+') rotate('+(p[2]*-33)+')">'+R(-5,-4,10,1.8,'#000')+R(-5,-1,10,1.8,'#000')+R(-5,2,10,1.8,'#000')+'</g>').join(''),
    aeb:()=>R(0,0,54,54,'#009C3B')+'<path d="M27 8L49 27 27 46 5 27z" fill="#FFDF00"/><circle cx="27" cy="27" r="10" fill="#002776"/><path d="M17.5 25q10-3 19 3" stroke="#fff" stroke-width="1.6" fill="none"/>',
    conae:()=>H3('#74ACDF','#fff','#74ACDF')+'<circle cx="27" cy="27" r="4.5" fill="#F6B40E" stroke="#85340A" stroke-width=".6"/>',
    uksa:()=>R(0,0,54,54,'#012169')+'<path d="M0 0L54 54M54 0L0 54" stroke="#fff" stroke-width="9"/><path d="M0 0L54 54M54 0L0 54" stroke="#C8102E" stroke-width="3"/><path d="M27 0V54M0 27H54" stroke="#fff" stroke-width="14"/><path d="M27 0V54M0 27H54" stroke="#C8102E" stroke-width="8"/>',
    aee:()=>R(0,0,54,54,'#AA151B')+R(0,13.5,54,27,'#F1BF00'),
