    const mk=(geo,m,arr,f,colf)=>{ if(!arr.length) return; const im=new THREE.InstancedMesh(geo,m,arr.length); im.userData.ids=arr.map(t=>t.id||null); TREEIM.push(im); im.castShadow=true; im.receiveShadow=true; arr.forEach((t,i)=>{ dummy.rotation.set(0,0,0); dummy.scale.set(1,1,1); f(t,dummy,i); dummy.updateMatrix(); im.setMatrixAt(i,dummy.matrix); C.set(colf?colf(t,i):'#ffffff').convertSRGBToLinear(); im.setColorAt(i,C); }); if(im.instanceColor) im.instanceColor.needsUpdate=true; built.add(im); };
