    [[0,1.25,0,.62],[.28,1.0,.18,.48],[-.26,1.05,-.12,.46]].forEach((c,j)=>mk(ico,leaf,kinds.round,(t,o)=>{ const s=t.s||1, r=hs(t.x,t.y); o.position.set(t.x+c[0]*s*(r>.5?1:-1),c[1]*s,t.y+c[2]*s); o.scale.set(c[3]*s,c[3]*s*.86,c[3]*s); o.rotation.set(r*3,r*5,0); },(t,i)=>RP[(Math.floor(hs(t.y,t.x)*6)+j)%6]));
