      if(w.st==='walk'){ w.u+=w.dir*w.sp*dt; if(w.u>w.L||w.u<0){ w.u=Math.max(0,Math.min(w.L,w.u)); w.dir*=-1; } w.t-=dt; if(w.t<=0){ const r=w.force?0:Math.random(), lg=r<.8&&PARK?PARK.legs(c.position.x,c.position.z,3):null; if(lg){ w.legs=lg; w.li=0; w.away=true; w.fx=c.position.x; w.fz=c.position.z; w.st='roam'; u.play('walk'); } else { w.st=r<.9?'sleep':r<.95?'sit':'idle'; w.t=w.st==='sleep'?12+Math.random()*14:5+Math.random()*7; u.play(w.st); } } }
      else if(w.st==='sleep'||w.st==='sit'||w.st==='idle'){ w.t-=dt; if(w.t<=0) back(); }
      else if(w.st==='roam'){ const P={legs:w.legs,i:w.li,x:w.fx,z:w.fz}; parkMove(w,P,w.sp*1.1,dt,()=>{ const r=Math.random(); w.st=r<.4?'sleep':r<.8?'sit':'idle'; w.t=w.st==='sleep'?8+Math.random()*10:3+Math.random()*5; u.play(w.st); },()=>{ w.away=false; w.legs=null; w.st='walk'; w.t=2+Math.random()*3; }); w.li=P.i; w.fx=P.x; w.fz=P.z; }
      else if(w.st==='wait'){ w.wt+=dt; const p=w.partner; if(!p||(p.hs!=='greet'&&p.hs!=='pet')||w.wt>12){ w.partner=null; w.cool=20; back(); } else { c.rotation.y+=ANGN2(Math.atan2(p.g.position.x-c.position.x,p.g.position.z-c.position.z)-c.rotation.y)*Math.min(1,dt*6); if(p.hs==='pet'){ w.st='pet'; w.t=Math.max(1.5,(p.petT||4)-(p.at||0)); u.play('sit'); } } }
      else if(w.st==='pet'){ w.t-=dt; const p=w.partner; if(p){ let da=Math.atan2(p.g.position.x-c.position.x,p.g.position.z-c.position.z)-c.rotation.y; da=Math.atan2(Math.sin(da),Math.cos(da)); c.rotation.y+=da*Math.min(1,dt*6); } if(w.t<=0){ w.partner=null; w.st='jump'; w.t=1.5; u.play('jump'); } }
      else if(w.st==='jump'){ w.t-=dt; if(w.hop){ const H=w.hop; H.t+=dt; const f=Math.min(1,H.t/.5); w.fx=H.x0+(H.tx-H.x0)*f; w.fz=H.z0+(H.tz-H.z0)*f; if(f>=1) w.hop=null; } if(w.t<=0) back(); }
