    let ahead=null; for(const L of [.6,1.2,1.9]){ ahead=hitEM(W.x+Math.sin(W.h)*L,W.z+Math.cos(W.h)*L,W,.15); if(ahead) break; }
    if(ahead){ if(W.luck==null) W.luck=Math.random()<.93; if(W.luck&&W.th==null) W.th=Math.atan2(ahead.nx,ahead.nz)+(Math.random()*1.8-.9); } else W.luck=null;
    if(W.th!=null){ const da=ANGN(W.th-W.h), tr=7*dt; W.h+=Math.abs(da)<tr?da:Math.sign(da)*tr; if(Math.abs(da)<.06) W.th=null; }
