  function toggle(on){ build(); open=on==null?!open:!!on; if(!open) custom=null; panel.hidden=!open; btn.classList.toggle('on',open); btn.setAttribute('aria-expanded',open?'true':'false'); document.body.classList.toggle('zopen',open); if(open){ draw(); opened=true; const c=panel.querySelector('.zft .primary'); if(c) c.focus({preventScroll:true}); } else if(btn) btn.focus({preventScroll:true}); }
  function refresh(){ build(); tick(); if(open) draw(); }
  return {build,toggle,refresh,note,scene,show,closeCustom,isOpen:()=>open,SPR};
